import java.io.DataInputStream;

public class VanyaAndScales {
    public static void main(String[] args) throws Exception {
        DataInputStream dis = new DataInputStream(System.in);
        int W = readInt(dis);
        int M = readInt(dis);

        int[] B = new int[101];
        int tmp = M;
        for (int i = 0; i < 100; i++) {
            B[i] = tmp % W;
            tmp /= W;
        }

        for (int i = 0; i < 100; i++) {
            if (B[i] > 1) {
                B[i] -= W;
                B[i + 1]++;
            }
        }

        for (int i = 0; i <= 100; i++) {
            if (B[i] < -1 || B[i] > 1) {
                System.out.println("NO");
                return;
            }
        }
        System.out.println("YES");
    }

    private static int readInt(DataInputStream dis) throws Exception {
        int ret = 0;
        int c = dis.read();
        while (c <= ' ') c = dis.read();
        boolean neg = false;
        if (c == '-') {
            neg = true;
            c = dis.read();
        }
        do {
            ret = ret * 10 + c - '0';
            c = dis.read();
        } while (c >= '0' && c <= '9');
        return neg ? -ret : ret;
    }
}
