#include <iostream>
#include <vector>
#include <string>
#include <cctype>

int readInt() {
    int ret = 0;
    int c = std::cin.get();
    while (isspace(c)) c = std::cin.get();
    bool neg = false;
    if (c == '-') {
        neg = true;
        c = std::cin.get();
    }
    while (isdigit(c)) {
        ret = ret * 10 + (c - '0');
        c = std::cin.get();
    }
    return neg ? -ret : ret;
}

int main() {
    int W = readInt();
    int M = readInt();

    std::vector<int> B(101, 0);
    int tmp = M;
    for (int i = 0; i < 100; i++) {
        B[i] = tmp % W;
        tmp /= W;
    }

    for (int i = 0; i < 100; i++) {
        if (B[i] > 1) {
            B[i] -= W;
            B[i + 1]++;
        }
    }

    for (int i = 0; i <= 100; i++) {
        if (B[i] < -1 || B[i] > 1) {
            std::cout << "NO" << std::endl;
            return 0;
        }
    }
    std::cout << "YES" << std::endl;
    return 0;
}
